insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('bd64bbf8-eb11-43e8-ae94-4ad0a02b5ef2', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Diferentes áreas del mundo están en alto riesgo de deforestación; el mapa muestra zonas importantes de deforestación entre 2004 y 2017. A su vez, para cada una de las áreas se indican las principales causas de deforestación local y las causas secundarias de deforestación.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-qmapa.webp" style="min-width:800px" loading="lazy" alt="Mapa de nueve áreas latinoamericanas y causas de deforestación: ganadería, agricultura, granjas, tala, leña, minería, infraestructura e incendios."><figcaption>Mapa de nueve áreas latinoamericanas y causas de deforestación: ganadería, agricultura, granjas, tala, leña, minería, infraestructura e incendios. Desliza para ver la figura completa.</figcaption></figure><p>La deforestación ocasiona otros problemas ambientales. El siguiente modelo muestra cómo es el flujo de carbono capturado y liberado por las plantas en toneladas (t) en un área protegida y no protegida de un bosque.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-qcarbono.webp" style="min-width:760px" loading="lazy" alt="Flujo de carbono en área protegida y no protegida: captura y liberación por deforestación y degradación."><figcaption>Flujo de carbono en área protegida y no protegida: captura y liberación por deforestación y degradación. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ef919c6b-2167-45c8-aaf1-bd1ded77392d', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Actualmente, algunos productos tecnológicos en buen estado se convierten en residuos electrónicos, principalmente los equipos de telecomunicaciones e informática, como televisores, radios, teléfonos celulares y computadores. En la siguiente gráfica se muestra la composición porcentual de estos residuos electrónicos.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-qresiduos.webp" style="min-width:530px" loading="lazy" alt="Composición de residuos electrónicos: metales 60%, plástico 15%, pantalla 12%, tarjetas de circuito 7%, metales tóxicos 3%, cables 2% y otros materiales 1%; desglose de metales."><figcaption>Composición de residuos electrónicos: metales 60%, plástico 15%, pantalla 12%, tarjetas de circuito 7%, metales tóxicos 3%, cables 2% y otros materiales 1%; desglose de metales. Desliza para ver la figura completa.</figcaption></figure><p>En un colegio, una encuesta muestra que el 82% de los estudiantes almacena sus residuos electrónicos en sus casas, pues no saben qué hacer con ellos, y un tratamiento inadecuado puede ocasionar graves impactos en el ambiente. Como estrategia de educación ambiental, en el colegio se va a realizar una jornada de clasificación de desechos electrónicos, para aprovechar los metales presentes y facilitar su disposición adecuada por parte de la empresa de recolección de basuras.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('42fdb7f5-61a7-42a9-a857-09db76d3d07e', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>La hemoglobina es una proteína férrica que se produce en la médula ósea a partir de alimentos ricos en átomos de hierro (Fe), cuya función principal es transportar el oxígeno desde los pulmones hacia los tejidos. Un déficit en esta proteína causa la enfermedad conocida como anemia.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d0869488-924a-4958-82c5-d41653cc04fd', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un estudio muestra que en una ciudad ha aumentado la tasa de enfermedades respiratorias por contaminación del aire con material particulado respirable (MP10). Ahora bien, para este estudio, se evaluó la relación entre la concentración de MP10 y el porcentaje de área dedicada a dos actividades: industria y urbanización, en cuatro zonas diferentes de la ciudad.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-q104.webp" style="min-width:450px" loading="lazy" alt="Porcentajes de área residencial e industrial y concentración de MP10 en Norte, Centro, Occidente y Sur."><figcaption>Porcentajes de área residencial e industrial y concentración de MP10 en Norte, Centro, Occidente y Sur. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d6e1afe0-88aa-4062-8919-0c3e2d1fe0b0', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En una especie de pato se pueden encontrar individuos con cuello corto e individuos con cuello largo. En esta especie se encuentra una mayor cantidad de patos con cuello largo. En un experimento se aparearon una hembra y un macho de cuello largo; de sus hijos 3/4 son de cuello largo y 1/4 son de cuello corto.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('594c05f4-95ea-4ddd-9b16-1add307c5806', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Un estudiante viene realizando un control a la producción de los residuos mensuales generados en su institución educativa. Los resultados de su labor se muestran en la siguiente tabla:</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Mes</th><th scope="col">Plástico y latas (kg)</th><th scope="col">Orgánico (kg)</th><th scope="col">Vidrio (kg)</th><th scope="col">Papel y cartón (kg)</th></tr></thead><tbody><tr><th scope="row">1</th><td>2</td><td>560</td><td>45</td><td>300</td></tr><tr><th scope="row">2</th><td>5</td><td>620</td><td>33</td><td>250</td></tr><tr><th scope="row">3</th><td>4</td><td>489</td><td>55</td><td>278</td></tr><tr><th scope="row">4</th><td>7</td><td>545</td><td>42</td><td>322</td></tr><tr><th scope="row">5</th><td>4</td><td>498</td><td>38</td><td>305</td></tr><tr><th scope="row">6</th><td>6</td><td>555</td><td>51</td><td>279</td></tr><tr><th scope="row">7</th><td>8</td><td>430</td><td>49</td><td>247</td></tr><tr><th scope="row">8</th><td>3</td><td>398</td><td>37</td><td>290</td></tr><tr><th scope="row">9</th><td>6</td><td>604</td><td>36</td><td>267</td></tr><tr><th scope="row">10</th><td>3</td><td>587</td><td>44</td><td>303</td></tr><tr><th scope="row">Total</th><td>48</td><td>5.286</td><td>430</td><td>2.841</td></tr></tbody></table></div><p>La alcaldía del municipio solicita a la institución reducir a la mitad la producción de residuos que se generan.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('37e14e87-c940-4439-9e99-8811a39e7cfd', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En la minería a cielo abierto se genera material particulado de un tamaño de 2,5 micrómetros PM₂,₅. Según la normatividad, la producción de PM₂,₅ debe ser menor de 37 µg/m³ y en algunas condiciones climáticas adversas deben superar los 55 µg/m³, si la exposición es de una duración de 24 horas. Concentraciones mayores podrían generar daños a la salud de las personas.</p><p><small>Nota sobre el original: la frase «deben superar» contradice la idea de un límite de exposición. Se conserva para hacer visible la errata del cuadernillo. Las preguntas siguientes se resuelven comparando el procedimiento y los datos de la tabla.</small></p><p>Una empresa dedicada a la minería a cielo abierto realiza una investigación para conocer las concentraciones emitidas durante el año 2018 y compararlas con las del año 2019, cuando se aumentaron las rutas de riego. Las rutas de riego son caminos donde unos aspersores distribuyen agua en pequeñas gotas que son expulsadas a presión. Las gotas recorren grandes distancias recogiendo material particulado y humectando el suelo. Los resultados de la investigación, para un centro de monitoreo, aparecen a continuación.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Rutas de riego</th><th scope="col">Aspersores</th><th scope="col">Fecha</th><th scope="col">Concentración aproximada de PM₂,₅ (µg/m³)</th></tr></thead><tbody><tr><th scope="row">2</th><td>3</td><td>31 de mayo de 2018</td><td>60</td></tr><tr><th scope="row">2</th><td>3</td><td>12 de junio de 2018</td><td>60</td></tr><tr><th scope="row">2</th><td>3</td><td>24 de junio de 2018</td><td>52</td></tr><tr><th scope="row">6</th><td>8</td><td>31 de mayo de 2019</td><td>52</td></tr><tr><th scope="row">6</th><td>8</td><td>12 de junio de 2019</td><td>51</td></tr><tr><th scope="row">6</th><td>8</td><td>24 de junio de 2019</td><td>37</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('817dd842-b176-4188-ba67-c4b6696f2abc', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Los aminoácidos, transportados por el ARN de transferencia (ARNt), inician el proceso de traducción cuando la información contenida en el ARN mensajero (ARNm) pasa por el ribosoma y traduce la información de las bases nitrogenadas. Estas, por su parte, se aparean y van uniendo los aminoácidos en el orden necesario para una proteína específica. A continuación, se muestra el proceso:</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-q110.webp" style="min-width:620px" loading="lazy" alt="ARN de transferencia con aminoácidos, anticodones, codones del ARN mensajero y ribosoma durante la traducción."><figcaption>ARN de transferencia con aminoácidos, anticodones, codones del ARN mensajero y ribosoma durante la traducción. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ee89d450-d5e5-4407-bef1-67eae6a782fb', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>En un experimento que buscaba indagar sobre las fluctuaciones en el tamaño poblacional de dos especies de escarabajos (una café y una verde) durante un periodo de seis años, se obtuvieron los resultados que se muestran en la siguiente tabla:</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Año</th><th scope="col">Escarabajos cafés</th><th scope="col">Escarabajos verdes</th></tr></thead><tbody><tr><th scope="row">1</th><td>300</td><td>280</td></tr><tr><th scope="row">2</th><td>276</td><td>302</td></tr><tr><th scope="row">3</th><td>225</td><td>240</td></tr><tr><th scope="row">4</th><td>201</td><td>245</td></tr><tr><th scope="row">5</th><td>280</td><td>299</td></tr><tr><th scope="row">6</th><td>277</td><td>267</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('626359c4-d8fd-46b5-b922-3f7afe86ad96', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Debido al crecimiento poblacional, los cultivos genéticamente modificados ofrecen una solución más eficaz para suplir la necesidad alimentaria frente a los cultivos tradicionales, puesto que permiten obtener un mayor rendimiento en las cosechas y requieren de un menor espacio para su producción, entre otros beneficios. En Colombia, el algodón y el maíz son los cultivos que lideran este tipo de técnica. En la siguiente gráfica se muestra el comportamiento de los dos cultivos en el país en un periodo de 12 años.</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-q113.webp" style="min-width:720px" loading="lazy" alt="Área sembrada de algodón y maíz en Colombia entre 2002 y 2014, en hectáreas."><figcaption>Área sembrada de algodón y maíz en Colombia entre 2002 y 2014, en hectáreas. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('739930b6-3d65-4864-ab31-46168a3b7fb2', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El intercambio genético entre nativos europeos, africanos y americanos sucedió hace más de 500 años durante la colonización europea. Algunos genes del ADN de los colombianos actuales conservan alelos de resistencia a la infección de malaria que son originarios de poblaciones africanas, la cual sigue siendo una de las principales causas de muerte en menores de 5 años en África y en América.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('bec1d419-00c1-424d-91c5-2009eaf03a07', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>El arsénico es un elemento que puede causar diferentes tipos de enfermedades según la cantidad y el tiempo a los que se esté expuesto. Carlos desea conocer cuál es el mecanismo de transporte de este elemento al interior de una célula. Investigando, encontró la siguiente imagen donde explican los diferentes tipos de transporte que hay (ver Figura 1).</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-q115-1.webp" style="min-width:620px" loading="lazy" alt="Figura 1: difusión simple, difusión facilitada y transporte activo que requiere ATP."><figcaption>Figura 1: difusión simple, difusión facilitada y transporte activo que requiere ATP. Desliza para ver la figura completa.</figcaption></figure><p>Además, en la información consultada mencionan que el arsénico tiene similitud con el fosfato (PO₄³⁻) e ingresa a la célula por la misma bomba transportadora de este compuesto (ver Figura 2).</p><figure class="ctx-fig es-ancha" tabindex="0"><img src="img/figuras/bio/b7-q115-2.webp" style="min-width:380px" loading="lazy" alt="Figura 2: ingreso de fosfato y arsénico a través de una proteína de membrana."><figcaption>Figura 2: ingreso de fosfato y arsénico a través de una proteína de membrana. Desliza para ver la figura completa.</figcaption></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7e881a13-08cb-427c-aea7-481ea8691002', 'situacion', 'BIOLOGÍA', 'ctx-sit', '<p>Después de una sesión de clase de gimnasia un estudiante se levanta con un fuerte dolor en el cuello. Acude al médico, quien le receta un analgésico oral de 50 mg cada 12 horas. Sin embargo, 30 horas después, el dolor permanece y el alivio es muy leve. Vuelve al médico y ahora le aplica el mismo analgésico, en igual concentración, pero de forma inyectable en el músculo, y en menos de una hora se puede percibir el alivio.</p>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '54666d34-a07a-4aa1-8cd0-01125ef01257', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'bd64bbf8-eb11-43e8-ae94-4ad0a02b5ef2', 'Ecosistemas y ciclos',
  'De acuerdo con el modelo de flujo de carbono, ¿qué ocurriría con el carbono liberado por deforestación y por degradación si en las áreas no protegidas se plantan árboles?',
  array['El carbono liberado por deforestación y por degradación aumentaría.', 'El carbono liberado por deforestación disminuiría y aumentaría el carbono liberado por degradación.', 'El carbono liberado por deforestación y por degradación disminuiría.', 'El carbono liberado por deforestación aumentaría y disminuiría el carbono liberado por degradación.'],
  'Compara ambas clases de liberación entre las áreas del modelo.', 'publicada', 'modelo', '1c00ecc6252e70a28c32348ca2e6a26d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('54666d34-a07a-4aa1-8cd0-01125ef01257', 2, 'El modelo relaciona la conservación de cobertura arbórea con menores pérdidas de carbono por deforestación y degradación. La recuperación del bosque se interpreta en ese sentido dentro del ejercicio.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
