insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('81e6cb81-b9b2-432a-b255-602bf31af9b2', 1, 'Los símbolos de ganadería y agricultura a gran escala aparecen como causas relevantes en numerosas áreas del mapa. La comparación debe abarcar las regiones, no una sola localidad.');

