insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a1855dad-5825-454b-808d-6ae3d7a0a7bf', 3, 'El mapa concentra múltiples áreas de riesgo y causas de deforestación alrededor de la región amazónica. Esta es la opción que reúne el conjunto más amplio de zonas señaladas.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7ca1b22d-3e3b-40a3-9e40-bbbb11c4c4c1', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'ef919c6b-2167-45c8-aaf1-bd1ded77392d', 'Ecosistemas y ciclos',
  'Después de la jornada de clasificación de residuos electrónicos, un estudiante propone quemar él mismo el material excedente para extraer los metales. ¿La anterior propuesta es ambientalmente correcta?',
  array['Sí, porque de esta manera los residuos electrónicos se pueden usar como combustible para reemplazar el carbón.', 'No, porque en el proceso de quema se pueden generar reacciones en otros materiales que pueden ser contaminantes.', 'Sí, porque las pantallas y plásticos son residuos aprovechables y los residuos de la quema se podrían usar como fertilizantes.', 'No, porque a los estudiantes les es difícil desprenderse de sus residuos electrónicos y prefieren darle un uso aprovechable en su casa.'],
  'Considera qué ocurre con los otros componentes durante la combustión.', 'publicada', 'modelo', '9d0a105fd76e17a7f86aa9eb4dd8bd69', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7ca1b22d-3e3b-40a3-9e40-bbbb11c4c4c1', 1, 'Quemar una mezcla de componentes electrónicos sin un tratamiento apropiado puede liberar sustancias contaminantes. Clasificar para una disposición adecuada no equivale a quemar los materiales en casa.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'cf6633e6-a7d5-4bd0-adc2-2ffc507d0c42', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  '42fdb7f5-61a7-42a9-a857-09db76d3d07e', 'Sistemas del cuerpo humano',
  'De acuerdo con lo anterior, ¿qué efecto podría tener la deficiencia de hierro en el cuerpo humano?',
  array['Alteración del ciclo circadiano.', 'Aumento de la masa corporal.', 'Disminución en la oxigenación de las células.', 'Cambios en el material genético de las células.'],
  'Relaciona el elemento con la función de la proteína que lo contiene.', 'publicada', 'modelo', 'cc2cf8a30b519839c0faa5863847e581', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cf6633e6-a7d5-4bd0-adc2-2ffc507d0c42', 2, 'El hierro forma parte de la hemoglobina. Una disminución de esta proteína reduce la capacidad de transportar oxígeno a los tejidos, que es la función señalada en el texto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '06b01278-3151-45af-98ef-dd80b55f9628', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'd0869488-924a-4958-82c5-d41653cc04fd', 'Ecosistemas y ciclos',
  'De acuerdo con la información y la gráfica, ¿cuál es una posible solución para disminuir la incidencia de enfermedades respiratorias en esta ciudad?',
  array['Reducir la actividad de la industria y distribuir las áreas industriales de manera equitativa por toda la ciudad.', 'Regular el crecimiento urbano y capacitar a los ciudadanos en prácticas que generen menos contaminación.', 'Regular el crecimiento industrial y realizar actividades de prevención en las zonas de mayor contaminación.', 'Regular el crecimiento urbano y aumentar el área industrial para que se genere menos contaminación.'],
  'Compara el patrón industrial con las barras de material particulado.', 'publicada', 'modelo', '7115ee40f918632c3306d366b6f05c8b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('06b01278-3151-45af-98ef-dd80b55f9628', 2, 'Las zonas con mayor actividad industrial muestran concentraciones altas de partículas. Regular esa actividad y dirigir la prevención a las zonas más contaminadas responde a la asociación observada, sin suponer que repartir la contaminación sea la solución.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'da99f2b0-9b4e-416c-979e-c668ae4b569d', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  'd6e1afe0-88aa-4062-8919-0c3e2d1fe0b0', 'Genética y herencia',
  'De los genotipos de los padres puede afirmarse que:',
  array['Ambos padres eran heterocigotos.', 'El macho era heterocigoto y la hembra homocigoto recesivo.', 'El macho era heterocigoto y la hembra homocigoto dominante.', 'Ambos padres eran homocigotos dominantes.'],
  'Representa el cruce que permite obtener un cuarto de descendientes recesivos.', 'publicada', 'modelo', '304ca2e6f15bf4a963317b285c5cc01b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('da99f2b0-9b4e-416c-979e-c668ae4b569d', 0, 'En el modelo mendeliano de dominancia completa, el cruce Ll × Ll produce 1/4 LL, 1/2 Ll y 1/4 ll: tres cuellos largos por uno corto. Ambos progenitores deben portar el alelo recesivo para producir descendencia ll.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'e7d8c82a-2835-4c99-aa1a-e260e7564c77', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '594c05f4-95ea-4ddd-9b16-1add307c5806', 'Ecosistemas y ciclos',
  'De acuerdo con lo solicitado por la alcaldía, ¿cuál de las siguientes propuestas le permitiría solucionar la problemática al estudiante?',
  array['Iniciar un programa de compostaje para aprovechar el material orgánico, papel y cartón.', 'Eliminar las canecas de reciclaje para evitar la producción de plástico, latas, papel y cartón.', 'Prohibir la venta de plásticos de un solo uso, botellas de vidrio y latas en la tienda escolar.', 'Realizar campañas en la comunidad que promuevan la reducción del material no reciclable.'],
  'Compara las masas totales antes de elegir una estrategia.', 'publicada', 'modelo', '9baeb46e823bb2897c56aefe5d8211ab', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e7d8c82a-2835-4c99-aa1a-e260e7564c77', 0, 'El residuo orgánico por sí solo representa más de la mitad del total registrado. Aprovecharlo mediante compostaje, junto con papel y cartón aptos para ese proceso, actúa sobre la fracción predominante. Plásticos, latas y vidrio suman mucho menos de la mitad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9549f513-c497-4e33-b117-e00cf52e22f2', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '37e14e87-c940-4439-9e99-8811a39e7cfd', 'Ecosistemas y ciclos',
  'Un estudiante desea comunicar la investigación realizada por la empresa en una cartelera, agregando información sobre el funcionamiento de los aspersores de agua. ¿En qué parte de la cartelera debería poner esta información?',
  array['En las conclusiones.', 'En los resultados.', 'En la metodología.', 'En el título.'],
  'Distingue cómo se hizo la investigación de lo que se encontró.', 'publicada', 'modelo', '92330b70f75a4261b9b2cc3337a7c6e2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9549f513-c497-4e33-b117-e00cf52e22f2', 2, 'El funcionamiento de los aspersores describe el instrumento y el procedimiento usados para intervenir el ambiente. Ese contenido corresponde a la metodología.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4f7d3b66-645b-4c86-ba49-5bd25e9dd3e0', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '37e14e87-c940-4439-9e99-8811a39e7cfd', 'Ecosistemas y ciclos',
  'De acuerdo con la información anterior, ¿por qué los investigadores toman las mediciones en las mismas fechas cada año?',
  array['Porque así se tienen en cuenta los resultados de diferentes centros de monitoreo.', 'Porque se esperan las mismas condiciones climáticas en las mismas épocas del año.', 'Porque en esas fechas del año las partículas difícilmente se suspenden en el aire.', 'Porque se garantiza la disminución de la cantidad de agua que utilizan los aspersores.'],
  'Identifica qué variable externa se intenta mantener comparable.', 'publicada', 'modelo', '47ca4db9da496f41a3862a07d6ca381c', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4f7d3b66-645b-4c86-ba49-5bd25e9dd3e0', 1, 'Comparar fechas de la misma época busca reducir diferencias estacionales que podrían afectar las mediciones. Eso no garantiza un clima idéntico, pero hace más comparable el diseño.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'aa0761ae-9ce6-4bf2-b530-159f227cc225', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  '37e14e87-c940-4439-9e99-8811a39e7cfd', 'Ecosistemas y ciclos',
  'De acuerdo con la información anterior, ¿qué debería hacer la empresa para mejorar la calidad del aire donde se encuentra el centro de monitoreo?',
  array['Disminuir los aspersores y las rutas de riego, porque así se aprovecharían las condiciones climáticas.', 'Aumentar los aspersores y las rutas de riego, porque así aumentarían los centros de monitoreo rápidamente.', 'Disminuir los aspersores y las rutas de riego, porque la concentración de PM₂,₅ en el aire ya está controlada.', 'Aumentar los aspersores y las rutas de riego, porque así disminuye la concentración de PM₂,₅ en el aire.'],
  'Compara las concentraciones de cada fecha antes y después de la intervención.', 'publicada', 'modelo', 'd5f913fd049f079a6a1ee3e9d43b5fae', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('aa0761ae-9ce6-4bf2-b530-159f227cc225', 3, 'Los registros de 2019, con más rutas y aspersores, son menores que los de las mismas fechas de 2018. La opción corresponde al efecto observado en este estudio, sin implicar que aumentar indefinidamente el riego sea siempre adecuado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c83ee07a-4e1a-4931-bdfd-ee3931d45609', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '817dd842-b176-4188-ba67-c4b6696f2abc', 'Genética y herencia',
  'Teniendo en cuenta esta información, ¿qué pasaría ante la ausencia del ARNt en la síntesis de proteínas?',
  array['Se detendría la producción de proteínas, puesto que el ARNt es el encargado de transportar aminoácidos específicos y aparearlos con el fin de iniciar el proceso de elongación.', 'No se vería afectada la producción de proteínas, ya que dependen únicamente del ARNm.', 'Se aumentaría la producción de proteínas, puesto que el ARNt controla el número de aminoácidos que son transportados al unir el codón y el anticodón en el citoplasma del ribosoma.', 'No se vería afectada la producción de proteínas, ya que el ARNt es reemplazado por el ARNm.'],
  'Distingue la función del mensaje de la del transportador.', 'publicada', 'modelo', '1ac8fc7e5e4808c614527e052f358e52', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c83ee07a-4e1a-4931-bdfd-ee3931d45609', 0, 'Sin ARNt no se pueden incorporar los aminoácidos correspondientes a los codones durante la traducción. El ARNm aporta la secuencia de información, pero no sustituye al transportador de aminoácidos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0dad94fb-0813-4282-adb1-d90ce64cf32e', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'ecosistemas'),
  (select id from public.lotes where codigo = '2026-B'),
  'ee89d450-d5e5-4407-bef1-67eae6a782fb', 'Ecosistemas y ciclos',
  'De acuerdo con el tipo de datos mostrados en la tabla, ¿cuál es la forma adecuada de representarlos gráficamente?',
  array['<img src="img/figuras/bio/b7-q111-a.webp" style="width:100%;max-width:460px" alt="Representación gráfica de las poblaciones de escarabajos durante seis años" loading="lazy">', '<img src="img/figuras/bio/b7-q111-b.webp" style="width:100%;max-width:460px" alt="Representación gráfica de las poblaciones de escarabajos durante seis años" loading="lazy">', '<img src="img/figuras/bio/b7-q111-c.webp" style="width:100%;max-width:460px" alt="Representación gráfica de las poblaciones de escarabajos durante seis años" loading="lazy">', '<img src="img/figuras/bio/b7-q111-d.webp" style="width:100%;max-width:460px" alt="Representación gráfica de las poblaciones de escarabajos durante seis años" loading="lazy">'],
  'Verifica las dos poblaciones en el año 4, donde sus valores son distintos.', 'publicada', 'modelo', '1e18df811575078c57877b59d599a6c7', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0dad94fb-0813-4282-adb1-d90ce64cf32e', 0, 'La representación seleccionada muestra por separado los tamaños de ambas poblaciones en cada año y corresponde a los valores de la tabla. Las otras opciones cambian valores, acumulan barras de manera incorrecta o convierten la serie temporal en proporciones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '0c51cc4d-4c41-441c-8eb3-69cf069e4475', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '626359c4-d8fd-46b5-b922-3f7afe86ad96', 'Genética y herencia',
  '¿Cómo pueden interpretarse los resultados de la gráfica frente a la relación que se presenta entre los dos tipos de cultivos?',
  array['La introducción del cultivo de maíz ha ido disminuyendo el cultivo de algodón.', 'En el último año se ha triplicado el cultivo de algodón respecto al cultivo de maíz.', 'El maíz comenzó a cultivarse primero que el algodón y siempre ha sido mayor.', 'En el año 2009 se presentó una disminución drástica en los dos tipos de cultivos.'],
  'Comprueba cada afirmación contra las fechas, las cifras y la diferencia entre asociación y causalidad.', 'borrador', 'modelo', 'bec11090312cff0d246ff2839bd3a426', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0c51cc4d-4c41-441c-8eb3-69cf069e4475', 0, 'Ninguna opción describe inequívocamente los datos. La gráfica no demuestra que el maíz cause una reducción del algodón; en 2014 el maíz (89.048) casi triplica al algodón (29.838), no al revés; el algodón aparece antes y en 2009 solo disminuye el algodón, mientras el maíz aumenta. Se conserva en borrador sin calificar una opción como válida.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4f1bd305-574b-4204-ae01-fa816f822b22', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'genetica-y-herencia'),
  (select id from public.lotes where codigo = '2026-B'),
  '739930b6-3d65-4864-ab31-46168a3b7fb2', 'Genética y herencia',
  'Teniendo en cuenta la información anterior, ¿cómo se puede explicar la persistencia de estos alelos de resistencia en el genoma de los colombianos en la actualidad?',
  array['Porque la malaria, al afectar procesos como la respiración celular, obligó a los colombianos a adquirir nuevos genes que les permitían vivir sin células.', 'Porque las personas con genes resistentes a la malaria pudieron sobrevivir a la infección y al reproducirse pasaron sus genes a las nuevas generaciones.', 'Porque la infección por malaria causa competencia entre los genes de los africanos y americanos, ocasionando que solo persista un único alelo.', 'Porque el genoma de todos los colombianos actualmente conserva por azar un tercio de los alelos de europeos, otro de africanos y otro de americanos.'],
  'Relaciona supervivencia, reproducción y transmisión de alelos.', 'publicada', 'modelo', '9a4e45309e4dbeef6332c39de30ec0ed', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4f1bd305-574b-4204-ae01-fa816f822b22', 1, 'Una variante heredable que favorece la supervivencia en un ambiente puede transmitirse con mayor frecuencia a la descendencia. Ese mecanismo combina selección natural y herencia; no implica que una necesidad produzca genes nuevos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6acb0ffd-b3ee-4b1f-89da-d37c33fada76', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'celula'),
  (select id from public.lotes where codigo = '2026-B'),
  'bec1d419-00c1-424d-91c5-2009eaf03a07', 'Célula y sus procesos',
  'Según la información brindada, ¿qué tipo de transporte utiliza el arsénico para ingresar a la célula?',
  array['Transporte activo, porque el arsénico se transporta de la parte más concentrada, requiriendo energía para ello.', 'Difusión facilitada, porque no se requiere energía, pero sí se utilizan proteínas de membrana para ingresar a la célula.', 'Transporte activo, porque se requiere de energía y de proteínas de membrana para ingresar a la célula.', 'Difusión simple, porque el arsénico no requiere energía ni proteínas de membrana para ingresar a la célula.'],
  'Combina la palabra «bomba» con la distinción entre los mecanismos de la figura 1.', 'publicada', 'modelo', '9188049525c18d773d715bf9d81c679a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6acb0ffd-b3ee-4b1f-89da-d37c33fada76', 2, 'El enunciado especifica una bomba transportadora, que en el modelo presentado corresponde al transporte activo con proteínas y gasto energético. La figura 2 por sí sola no muestra ATP; la identificación depende de esa información verbal.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fe3351a0-9c9c-453e-907f-311ce947dd3f', 'bio',
  (select id from public.temas where materia = 'bio' and codigo = 'cuerpo-humano'),
  (select id from public.lotes where codigo = '2026-B'),
  '7e881a13-08cb-427c-aea7-481ea8691002', 'Sistemas del cuerpo humano',
  '¿Cuál de las siguientes opciones corresponde a una explicación lógica de este fenómeno?',
  array['El analgésico oral tiene mayor concentración, por lo que disminuye la cantidad de sangre en las venas y genera dolor en el cuello.', 'El medicamento recetado de forma inyectable tiene el doble de concentración y produjo una intoxicación en el estudiante.', 'El analgésico inyectable está hecho a base de un compuesto con más átomos que el analgésico oral para que actúe más rápido.', 'El medicamento inyectado se absorbe más rápidamente que el medicamento oral porque no tiene que ser digerido en el estómago.'],
  'Mantén constantes la sustancia y la concentración; identifica qué cambió.', 'publicada', 'modelo', 'e85f56fe2a4ec2cc6a51b03cda49cf65', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fe3351a0-9c9c-453e-907f-311ce947dd3f', 3, 'En el caso descrito, la diferencia compatible con los datos es la vía de administración y absorción, no un cambio de concentración o de molécula. «Ser digerido» es una simplificación del cuadernillo: la vía oral requiere liberación y absorción gastrointestinal. La rapidez relativa depende del fármaco y de su formulación.');

