insert into public.cuestionarios (id, materia, slug, seccion, titulo, tipo, orden, lote_id, publicado)
select '2d8671f0-665b-442a-9214-c0d65f2a4b0b', 'bio', 'bio-13', 'Célula y sus procesos', '7B · Célula y sus procesos', 'Práctica', 13,
  (select id from public.lotes where codigo = '2026-B'), true;
insert into public.cuestionario_preguntas (cuestionario_id, pregunta_id, orden) values ('2d8671f0-665b-442a-9214-c0d65f2a4b0b', '6acb0ffd-b3ee-4b1f-89da-d37c33fada76', 1);

